import os
import sqlite3
import hashlib
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        department TEXT DEFAULT 'general'
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        action TEXT,
        target_user TEXT,
        performed_by TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by department. Requires valid API key."""
    api_key = request.headers.get('X-API-Key', '')
    if not _validate_api_key(api_key):
        return jsonify({'error': 'unauthorized'}), 401

    department = request.args.get('dept', '')
    include_inactive = request.args.get('include_inactive', 'false')

    # Build query with department filter
    # Note: using parameterized query for the boolean flag
    if include_inactive == 'true':
        query = f"SELECT username, role, department FROM users WHERE department = '{department}'"
    else:
        query = f"SELECT username, role, department FROM users WHERE department = '{department}' AND role != 'inactive'"

    try:
        db = get_db()
        results = db.execute(query).fetchall()
        return jsonify({'users': [dict(r) for r in results]})
    except Exception as e:
        app.logger.error(f"Query error: {e}")
        return jsonify({'error': 'internal error'}), 500

@app.route('/api/users/lookup', methods=['POST'])
def lookup_user():
    """Lookup specific user by username. Uses parameterized query."""
    api_key = request.headers.get('X-API-Key', '')
    if not _validate_api_key(api_key):
        return jsonify({'error': 'unauthorized'}), 401

    data = request.get_json()
    username = data.get('username', '')

    db = get_db()
    result = db.execute(
        "SELECT username, role, department FROM users WHERE username = ?",
        (username,)
    ).fetchone()

    if result:
        return jsonify({'user': dict(result)})
    return jsonify({'error': 'not found'}), 404

@app.route('/api/audit', methods=['GET'])
def get_audit_log():
    """Retrieve audit log entries. Admin only."""
    api_key = request.headers.get('X-API-Key', '')
    if not _validate_api_key(api_key):
        return jsonify({'error': 'unauthorized'}), 401

    limit = request.args.get('limit', '50')
    # Sanitize limit to integer
    try:
        limit = int(limit)
    except ValueError:
        limit = 50

    db = get_db()
    results = db.execute(
        "SELECT * FROM audit_log ORDER BY timestamp DESC LIMIT ?",
        (limit,)
    ).fetchall()
    return jsonify({'entries': [dict(r) for r in results]})

def _validate_api_key(key):
    """Validate API key against stored hash."""
    if not key:
        return False
    expected_hash = os.environ.get('API_KEY_HASH', '')
    return hashlib.sha256(key.encode()).hexdigest() == expected_hash

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
